#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# patch_global_anchor.py
# ─────────────────────────────────────────────────────────────
# ГЛОБАЛЬНЫЙ ЯКОРЬ — честный тренд большой воды (x5 ТФ вверх).
#
# БОЛЕЗНЬ: трейдеры входили против глобального тренда, т.к. global_bias
# мерился по синей линии РАБОЧЕГО этажа (приближение, не старший этаж).
# ЛЕКАРСТВО: global_bias = веер Аллигатора СТАРШЕГО этажа (рабочий x5
# вверх по лесенке), мерян на дату бара (без заглядывания в будущее).
# §12 Котина: "вход в сторону глобального тренда".
#
# ТИХАЯ ПОДМЕНА: поле global_bias то же — трейдеры/Искра/Ганс читают
# как читали, меняется только содержимое. Промпты НЕ тронуты. Аллигатор
# рабочего НЕ тронут (по книжке). Math ядра НЕ тронута — одна вставка
# подменяет переменную global_bias до укладки в стол.
#
# Идёт через ЯДРО build_market_data → честный ветер во ВСЕХ прогонах:
# твой тестер, реал, единый движок — все собирают стол через ядро.
#
# ТРЕБУЕТ путь 2 (feed_source.py — источник старших баров). Кладётся ПОВЕРХ.
#
# Кладёт:  studio/modules/trading/global_anchor.py  (новый)
# Правит:  studio/modules/trading/williams_core.py  (1 вставка, math цела)
#
# Идемпотентно: маркер, бэкап .bak, откат правки при сломе синтаксиса.
# Запуск из КОРНЯ репы:  python patch_global_anchor.py
# ─────────────────────────────────────────────────────────────
import sys, py_compile, shutil, base64
from datetime import datetime
from pathlib import Path

MARKER = "ENGINE_ONE_DOOR_V1"
TRADING = Path("studio/modules/trading")
ANCHOR_B64 = ""
CORE_OLD = '    # Компас глобального фона из синей линии (Jaw).  # GLOBAL_BIAS_COMPASS_V1\n    # Факт направления, всегда на столе (не зависит от дивера/терминала).\n    global_bias = compute_global_bias(bars, alligator, _point)'
CORE_NEW = '    # Компас глобального фона из синей линии (Jaw).  # GLOBAL_BIAS_COMPASS_V1\n    # Факт направления, всегда на столе (не зависит от дивера/терминала).\n    global_bias = compute_global_bias(bars, alligator, _point)\n\n    # ENGINE_ONE_DOOR_V1: честный глобальный тренд — веер Аллигатора\n    # СТАРШЕГО этажа (рабочий x5 вверх по лесенке), мерян на дату текущего\n    # бара (без заглядывания в будущее). §12 Котина: фильтр большой воды.\n    # Подменяет синюю рабочего (она была приближением, не старшим этажом).\n    # Аллигатор рабочего НЕ тронут — старший меряется отдельно через источник.\n    # Якорь упал / источник недоступен -> остаётся синяя (фоллбэк, стол цел).\n    try:\n        from studio.modules.trading.global_anchor import global_trend as _gt\n        _bar_time = bars[-1].get("date") if bars else None\n        _r = _gt(symbol, timeframe, as_of_date=_bar_time)\n        if _r.get("ok"):\n            global_bias = _r["bias"]\n    except Exception:\n        pass  # любой сбой — оставляем синюю из compute_global_bias'

def _backup(p):
    bak = p.with_suffix(p.suffix + f".bak_{datetime.now():%Y%m%d_%H%M%S}")
    shutil.copy2(p, bak); return bak

def main():
    if not TRADING.exists():
        print(f"❌ Нет {TRADING} — запусти из КОРНЯ репы"); sys.exit(1)
    if not (TRADING / "feed_source.py").exists():
        print("⚠️  Нет feed_source.py — сперва путь 2 (patch_engine_path2.py). Стоп.")
        sys.exit(1)
    print("─"*60)
    print("  ГЛОБАЛЬНЫЙ ЯКОРЬ · честный тренд x5 через ядро")
    print("─"*60)
    # 1. новый файл якоря
    ap = TRADING / "global_anchor.py"
    if ap.exists(): print(f"  ↻ global_anchor.py: бэкап {_backup(ap).name}")
    ap.write_text(base64.b64decode(ANCHOR_B64).decode("utf-8"), encoding="utf-8")
    py_compile.compile(str(ap), doraise=True)
    print("  ✓ global_anchor.py: записан")
    # 2. правка ядра
    cp = TRADING / "williams_core.py"
    if not cp.exists():
        print("  ❌ нет williams_core.py"); sys.exit(1)
    text = cp.read_text(encoding="utf-8")
    if MARKER in text and CORE_NEW.strip()[:40] in text:
        print("  = williams_core.py: подмена уже стоит — пропуск")
    elif CORE_OLD not in text:
        print("  ⚠ williams_core.py: якорь не найден — НЕ тронут (проверь вручную)")
    else:
        bak = _backup(cp)
        cp.write_text(text.replace(CORE_OLD, CORE_NEW, 1), encoding="utf-8")
        try:
            py_compile.compile(str(cp), doraise=True)
            print(f"  ✓ williams_core.py: подмена легла (бэкап {bak.name})")
        except py_compile.PyCompileError as e:
            shutil.copy2(bak, cp)
            print(f"  ❌ сломало синтаксис — ОТКАЧЕНО ({e})"); sys.exit(1)
    print("─"*60)
    print("  ✅ global_bias теперь честный (веер старшего этажа, x5).")
    print("     Работает во ВСЕХ прогонах. Math/Аллигатор/промпты целы.")
    print("─"*60)

if __name__ == "__main__":
    main()
